"""Three helpers shared by the watchdog scripts: ask n8n, measure age, post to Slack.

No error handling on purpose. If n8n is down or Slack refuses the card, the
script crashes, exits non-zero, and Hermes sends you that failure itself.
"""

import os
from datetime import datetime, timezone

import requests

N8N = "http://localhost:5678"

RED = "#e01e5a"
AMBER = "#ecb22e"
GREEN = "#2eb67d"


def latest_execution(workflow_id):
    """The most recent run of a workflow, or None if it has never run."""
    r = requests.get(
        f"{N8N}/api/v1/executions",
        params={"workflowId": workflow_id, "limit": 1},
        headers={"X-N8N-API-KEY": os.environ["N8N_API_KEY"]},
    )
    r.raise_for_status()
    runs = r.json()["data"]
    return runs[0] if runs else None


def hours_since(timestamp):
    """Hours between an n8n timestamp and now. n8n sends UTC ending in Z."""
    started = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
    return (datetime.now(timezone.utc) - started).total_seconds() / 3600


def send_card(webhook_var, color, title, left, right, footer):
    """Post one Slack card. `left` and `right` are the two columns."""
    # No top-level "text": Slack renders it as a plain line above the card,
    # which just repeats the title. Tested against the webhook - a payload with
    # attachments and no text is accepted and answers "ok".
    payload = {
        "attachments": [{
            "color": color,
            "blocks": [
                {"type": "section",
                 "text": {"type": "mrkdwn", "text": title}},
                {"type": "section",
                 "fields": [{"type": "mrkdwn", "text": left},
                            {"type": "mrkdwn", "text": right}]},
                {"type": "context",
                 "elements": [{"type": "mrkdwn", "text": footer}]},
            ],
        }],
    }

    r = requests.post(os.environ[webhook_var], json=payload, timeout=20)
    # Slack answers a good card with HTTP 200 and the body "ok". Anything else is a problem.
    if r.text.strip() != "ok":
        raise RuntimeError(f"Slack refused the card: {r.status_code} {r.text.strip()}")
